repo.invoices.py:
"""Invoice records."""


class Invoice:
    def __init__(self, client, due):
        self.client = client
        self.due = due

    def __repr__(self):
        return "Invoice(%r, %r)" % (self.client, self.due)


ROWS = [('kite', 10), ('hale', 50), ('hale', 13), ('ivory', 52), ('hale', 44)]


def load_invoices():
    """Yield the stored invoices one at a time."""
    for client, due in ROWS:
        yield Invoice(client, due)

