"""Top invoices by due."""


def _take_largest(invoices):
    """Remove and return the invoice with the largest due."""
    best = max(invoices, key=lambda x: x.due)
    invoices.remove(best)
    return best


def podium(invoices, places=3):
    """Return the top `places` invoices by due, largest first. The caller's list is left as it was."""
    top = []
    while invoices and len(top) < places:
        top.append(_take_largest(invoices))
    return top


def report(invoices):
    """Return the podium values, the number of invoices and every due."""
    return {"podium": [x.due for x in podium(invoices)], "count": len(invoices), "all": [x.due for x in invoices]}

