from invoices import load_invoices, ROWS
from ranking import podium, report

VALUES = [v for _, v in ROWS]


def test_count():
    assert report(list(load_invoices()))["count"] == len(ROWS)


def test_all_values_kept():
    assert report(list(load_invoices()))["all"] == VALUES


def test_podium_values():
    top = podium(list(load_invoices()))
    assert [x.due for x in top] == sorted(VALUES, reverse=True)[:3]


def test_caller_list_unchanged():
    data = list(load_invoices())
    podium(data, 2)
    assert [x.due for x in data] == VALUES


def test_one_place():
    assert [x.due for x in podium(list(load_invoices()), 1)] == [max(VALUES)]
